// Binary plists shaped like the user_info of a voice-message attachment in
// chat.db: a dict with "audio-transcription" next to the attachment's
// decryption key, download URL and signature. Generated with Python's
// plistlib (fmt=FMT_BINARY) so the parser is tested against a real encoder,
// not one written alongside it. Values are placeholders.

const b64 = (s: string) => Buffer.from(s, "base64");

// 14 chars: length stored inline in the string's marker byte.
export const INLINE_LENGTH = b64(
  "YnBsaXN0MDDSAQIDBF8QE2F1ZGlvLXRyYW5zY3JpcHRpb25UbmFtZV5CZSByaWdodCB0aGVyZV8QEUF1ZGlvIE1lc3NhZ2UuY2FmCA0jKDcAAAAAAAABAQAAAAAAAAAFAAAAAAAAAAAAAAAAAAAASw=="
);

// "Running ten minutes late", alongside every key a real user_info carries.
export const WITH_SENSITIVE_KEYS = b64(
  ""
);

// 900 ASCII chars: length stored as a following 2-byte integer, like the
// 750 to 1,800 character transcripts seen on a real Mac.
export const LONG_TRANSCRIPT = b64(
  ""
);

// Non-ASCII text, which plist stores as UTF-16 big-endian, including an
// emoji that needs a surrogate pair.
export const UNICODE = b64(
  ""
);

// Same keys minus "audio-transcription": an audio message not yet transcribed.
export const NO_TRANSCRIPT = b64(
  ""
);

// Top-level array containing the key as a plain string, not a dict.
export const TOP_LEVEL_ARRAY = b64(
  "YnBsaXN0MDCiAQJfEBNhdWRpby10cmFuc2NyaXB0aW9uWm5vdCBhIGRpY3QICyEAAAAAAAABAQAAAAAAAAADAAAAAAAAAAAAAAAAAAAALA=="
);
